// One message per customer, naming the actual piece and the actual room.
//
// Deliberately not model-generated: this send is fully automated, and a
// template is auditable in a way a per-customer generation is not. The AI
// drafting path in the app is the one a rep approves before it goes out.
const rupees = (n) =>
  '\u20b9' + Number(n).toLocaleString('en-IN', { maximumFractionDigits: 0 });

const room = $json.room.replace('-', ' ');
const pct = $json.completion_pct;

return [{
  json: {
    customer_id: $json.customer_id,
    subject: `Your ${room} is ${pct}% complete`,
    body: [
      `Hi ${$json.customer_name},`,
      ``,
      `Your ${room} is coming together \u2014 ${pct}% complete since you chose the ${$json.anchor_title}.`,
      ``,
      `The piece most people add next is the ${$json.next_best_title} (${rupees($json.next_best_price)}).`,
      ``,
      `\u2014 Cadence`
    ].join('\n'),
    _debug_attach_rate: $json.next_best_attach_rate,
    _debug_window_days: $json.window_closes_in_days
  }
}];

// Low-confidence suggestions become a rep's queue, not an automated send.
return [{
  json: {
    queue: 'manual-review',
    customer_id: $json.customer_id,
    room: $json.room,
    suggestion: $json.next_best_title,
    attach_rate: $json.next_best_attach_rate,
    reason: 'attach rate below the 25% automation threshold'
  }
}];
